={{ JSON.stringify({ query: "query DashboardProducts($after: String) {
  locations(first: 100) { nodes { id legacyResourceId name isActive } }
  products(first: 2, after: $after, sortKey: ID) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id legacyResourceId title descriptionHtml handle status vendor productType tags templateSuffix
      createdAt updatedAt publishedAt
      seo { title description }
      options { id name position values }
      featuredMedia { preview { image { url width height } } }
      media(first: 100) { nodes { id mediaContentType alt status preview { image { url width height } } } }
      collections(first: 100) { nodes { id legacyResourceId title handle updatedAt } }
      metafields(first: 100) { nodes { id legacyResourceId namespace key type value jsonValue createdAt updatedAt } }
      variants(first: 100) {
        nodes {
          id legacyResourceId title displayName sku barcode position price compareAtPrice
          inventoryQuantity inventoryPolicy taxable createdAt updatedAt
          selectedOptions { name value }
          image { url width height }
          inventoryItem {
            id legacyResourceId tracked requiresShipping
            unitCost { amount currencyCode }
            measurement { weight { value unit } }
          }
        }
      }
    }
  }
}", variables: { after: $json.after } }) }}

