const response = $json.data?.products;
if (!response || !response.pageInfo || !Array.isArray(response.nodes)) throw new Error('SHOPIFY_PRODUCTS_RESPONSE_INVALID');
const numericId = gid => Number(String(gid || '').split('/').pop()) || null;
const runStartedAt = $json.runStartedAt;
const now = new Date().toISOString();
const locations = Object.fromEntries(($json.data?.locations?.nodes || []).map(l => [String(l.legacyResourceId || numericId(l.id)), l.name || null]));
const products = [];
const variants = [];
const inventoryItemIds = [];
const variantByInventoryItem = {};
for (const p of response.nodes) {
  const productId = Number(p.legacyResourceId) || numericId(p.id);
  if (!Number.isSafeInteger(productId)) throw new Error('SHOPIFY_PRODUCT_ID_INVALID');
  products.push({
    shopify_product_id: productId, title: p.title, description_html: p.descriptionHtml || null,
    handle: p.handle, status: String(p.status || '').toLowerCase(), vendor: p.vendor,
    product_type: p.productType, tags: p.tags || [], template_suffix: p.templateSuffix || null,
    image_url: p.featuredMedia?.preview?.image?.url || null,
    published_at: p.publishedAt || null, shopify_created_at: p.createdAt || null,
    shopify_updated_at: p.updatedAt, seo_title: p.seo?.title || null,
    seo_description: p.seo?.description || null, options: p.options || [],
    media: (p.media?.nodes || []).map(m => ({ id: m.id, type: m.mediaContentType, alt: m.alt, status: m.status, preview: m.preview?.image || null })),
    collections: (p.collections?.nodes || []).map(c => ({ id: c.legacyResourceId || numericId(c.id), title: c.title, handle: c.handle, updatedAt: c.updatedAt })),
    metafields: (p.metafields?.nodes || []).map(m => ({ id: m.legacyResourceId || numericId(m.id), namespace: m.namespace, key: m.key, type: m.type, value: m.value, jsonValue: m.jsonValue, createdAt: m.createdAt, updatedAt: m.updatedAt })),
    last_seen_at: runStartedAt, is_deleted: false, deleted_at: null, synced_at: now, updated_at: now,
  });
  for (const v of p.variants?.nodes || []) {
    const variantId = Number(v.legacyResourceId) || numericId(v.id);
    const inventoryItemId = Number(v.inventoryItem?.legacyResourceId) || numericId(v.inventoryItem?.id);
    if (!Number.isSafeInteger(variantId)) throw new Error('SHOPIFY_VARIANT_ID_INVALID');
    if (inventoryItemId) { inventoryItemIds.push(inventoryItemId); variantByInventoryItem[String(inventoryItemId)] = variantId; }
    variants.push({
      shopify_variant_id: variantId, shopify_product_id: productId, title: v.title,
      sku: v.sku, barcode: v.barcode, position: v.position, price: Number(v.price || 0),
      compare_at_price: v.compareAtPrice == null ? null : Number(v.compareAtPrice),
      unit_cost: v.inventoryItem?.unitCost?.amount == null ? null : Number(v.inventoryItem.unitCost.amount),
      unit_cost_currency: v.inventoryItem?.unitCost?.currencyCode || null,
      inventory_quantity: v.inventoryQuantity, inventory_policy: String(v.inventoryPolicy || '').toLowerCase() || null,
      taxable: v.taxable, image_url: v.image?.url || p.featuredMedia?.preview?.image?.url || null,
      inventory_item_id: inventoryItemId, selected_options: v.selectedOptions || [],
      weight: v.inventoryItem?.measurement?.weight?.value == null ? null : Number(v.inventoryItem.measurement.weight.value),
      weight_unit: v.inventoryItem?.measurement?.weight?.unit || null,
      requires_shipping: v.inventoryItem?.requiresShipping ?? null, tracked: v.inventoryItem?.tracked ?? null,
      shopify_created_at: v.createdAt || null, shopify_updated_at: v.updatedAt,
      last_seen_at: runStartedAt, is_deleted: false, deleted_at: null, synced_at: now, updated_at: now,
    });
  }
}
return [{ json: {
  runStartedAt, end: $json.end, after: $json.after, page: Number($json.page), maxPages: Number($json.maxPages),
  pagesRead: Number($json.pagesRead || 0), productsRead: Number($json.productsRead || 0),
  variantsRead: Number($json.variantsRead || 0), inventoryLevelsRead: Number($json.inventoryLevelsRead || 0),
  products, variants, inventoryItemIds: [...new Set(inventoryItemIds)], variantByInventoryItem, locations,
  pageInfo: response.pageInfo,
} }];

const b = $('Normalize Inventory Levels').item.json;
const pagesRead = b.pagesRead + 1;
const hasNextPage = Boolean(b.pageInfo?.hasNextPage);
if (hasNextPage && pagesRead >= b.maxPages) throw new Error('SHOPIFY_PRODUCTS_PAGE_LIMIT_REACHED:' + b.maxPages);
if (hasNextPage && !b.pageInfo?.endCursor) throw new Error('SHOPIFY_PRODUCTS_CURSOR_MISSING');
return [{ json: {
  runStartedAt: b.runStartedAt, end: b.end, after: hasNextPage ? b.pageInfo.endCursor : null,
  page: b.page + 1, maxPages: b.maxPages, pagesRead,
  productsRead: b.productsRead + b.products.length, variantsRead: b.variantsRead + b.variants.length,
  inventoryLevelsRead: b.inventoryLevelsRead + b.inventoryLevels.length, continue: hasNextPage,
} }];

const b = $('Normalize Complete Products and Variants').item.json;
const now = new Date().toISOString();
const inventoryLevels = ($json.inventory_levels || []).map(level => {
  const inventoryItemId = Number(level.inventory_item_id);
  const variantId = b.variantByInventoryItem[String(inventoryItemId)];
  if (!variantId) throw new Error('INVENTORY_LEVEL_VARIANT_NOT_FOUND:' + inventoryItemId);
  return {
    shopify_variant_id: variantId, shopify_inventory_item_id: inventoryItemId,
    shopify_location_id: Number(level.location_id), location_name: b.locations[String(level.location_id)] || null,
    available: level.available == null ? null : Number(level.available), shopify_updated_at: level.updated_at || null,
    last_seen_at: b.runStartedAt, is_deleted: false, deleted_at: null, synced_at: now, updated_at: now,
  };
});
return [{ json: { ...b, inventoryLevels } }];
